// Источник: web-тест .qa/e2e/tests/achievements/ac-01-grid-six-achievements.spec.ts, план .qa/e2e/specs/achievements.md (15.1), кейс .qa/tests/achievements/AC-01-achievements-grid.md
// Тикет #6a86f7ed. Опора: «הישגים ואבני דרך» AC1 (6 штук, решение 06.09), AC4 (полученные и неполученные различимы).
// Предусловие user1: получены «תפילה ראשונה», «3 ימים רצופים», «30 תפילות», «100 תפילות»; не получены «שבוע שלם», «חודש רצוף».
import { $$, driver, expect } from '@wdio/globals';
import { byLabel, byText, byTextContains, tapText, scrollToText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const ACHIEVED = ['תפילה ראשונה', '3 ימים רצופים', '30 תפילות', '100 תפילות'];
const NOT_ACHIEVED = ['שבוע שלם', 'חודש רצוף'];
const ALL = ['תפילה ראשונה', '3 ימים רצופים', 'שבוע שלם', '30 תפילות', 'חודש רצוף', '100 תפילות'];

function badges(re: string) {
  return driver.isAndroid
    ? $$(`android=new UiSelector().descriptionMatches("${re}")`).getElements()
    : $$(`-ios predicate string:name MATCHES "${re}"`).getElements();
}

describe('Достижения', () => {
  afterEach(async () => { await toHome(); });

  it('AC-01 Сетка 6 достижений — полученные и неполученные различимы, без дублей #6a86f7ed @prod-safe', async () => {
    // 1. «המסע שלי» → блок «הישגים».
    await goTab('המסע שלי');
    await (await byText('המסע שלי')).waitForDisplayed({ timeout: 20000 });
    const w = await byTextContains('עלית דרגה');
    if (await w.waitForDisplayed({ timeout: 1500 }).then(() => true, () => false)) await tapText('סגירה');
    await scrollToText('הישגים');
    await scrollToText('חודש רצוף');

    // 2. Ровно 6, каждое название — один раз.
    expect((await badges('.+: (הושג|טרם הושג)')).length).toBe(6);
    for (const name of ALL) expect((await badges(`${name}: (הושג|טרם הושג)`)).length).toBe(1);

    // Полученные: подпись «<имя>: הושג», нажимаемые (role=button в web).
    for (const name of ACHIEVED) {
      const el = await byLabel(`${name}: הושג`);
      await expect(el).toBeExisting();
      if (driver.isAndroid) expect(await el.getAttribute('clickable')).toBe('true');
    }
    // Неполученные: подпись «<имя>: טרם הושג», не кнопка.
    for (const name of NOT_ACHIEVED) {
      const el = await byLabel(`${name}: טרם הושג`);
      await expect(el).toBeExisting();
      if (driver.isAndroid) expect(await el.getAttribute('clickable')).not.toBe('true');
    }
  });
});
